#!/usr/bin/env node
import {
  runPipeline
} from "./chunk-XW73TKNN.js";
import {
  getErrorMessage
} from "./chunk-IXNX2GX7.js";

// src/services/checker.ts
import { readFile } from "fs/promises";
import pLimit from "p-limit";
import { warningSeverityOf } from "@gram-lang/modules";
import { GramParseError } from "@gram-lang/parser";
function diagnosticLevel(severity, strict) {
  return strict && severity !== "error" ? "error" : severity;
}
async function errorToDiagnostic(file, err) {
  const message = getErrorMessage(err);
  let line;
  if (err instanceof GramParseError) {
    try {
      const content = await readFile(file, "utf-8");
      line = getLineFromOffset(content, err.offset);
    } catch {
      line = void 0;
    }
  } else {
    const lineMatch = message.match(/line[: ]+(\d+)/i);
    line = lineMatch ? parseInt(lineMatch[1], 10) : void 0;
  }
  return {
    level: "error",
    category: "Structure",
    file,
    message,
    line
  };
}
function getLineFromOffset(content, offset) {
  if (offset == null) return void 0;
  return content.slice(0, offset).split("\n").length;
}
async function checkFiles(files, opts = {}) {
  const limit = pLimit(20);
  const diagnostics = [];
  await Promise.all(
    files.map(
      (file) => limit(async () => {
        try {
          const { content, compiled, analyzed } = await runPipeline(file, {
            db: opts.db,
            paths: opts.paths,
            stock: opts.stock
          });
          for (const w of compiled.warnings) {
            diagnostics.push({
              level: diagnosticLevel(warningSeverityOf(w.code), opts.strict),
              category: "Structure",
              file,
              message: w.message,
              line: getLineFromOffset(content, w.loc?.start)
            });
          }
          if (analyzed) {
            for (const id of analyzed.missingIngredients) {
              diagnostics.push({
                level: "warning",
                category: "Database",
                file,
                message: `"${id}" not found in ingredient database.`
              });
            }
          }
        } catch (err) {
          diagnostics.push(await errorToDiagnostic(file, err));
        }
      })
    )
  );
  return {
    diagnostics,
    hasErrors: diagnostics.some((d) => d.level === "error"),
    fileCount: files.length
  };
}

export {
  checkFiles
};
